};
const NOMES = {
  clean: 'ambiente', drink: 'bebida', perfume: 'perfume',
  alcohol70_spray: 'álcool 70 (spray)', alcohol70_hands: 'álcool 70 (mãos)', mouthwash: 'enxaguante',
};

const detectarEscuro = () => {
  const tema = context.grafana && context.grafana.theme;
  if (tema && typeof tema.isDark === 'boolean') {
    return tema.isDark;
  }
  const rgb = (getComputedStyle(document.body).backgroundColor.match(/[\d.]+/g) || []).map(Number);
  if (rgb.length < 3 || rgb[3] === 0) {
    return false;
  }
  return 0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2] < 128;
};
const escuro = detectarEscuro();
const tinta = escuro ? '#c3c2b7' : '#52514e';
const tintaForte = escuro ? '#f0efec' : '#0b0b0b';
const grade = escuro ? '#33332f' : '#e6e5e1';
const superficie = escuro ? '#1a1a19' : '#fcfcfb';
const cores = escuro ? PALETA.escuro : PALETA.claro;

const corDoCaso = (caso) => cores[caso] || cores.outro;
const nomeDoCaso = (caso) => NOMES[caso] || caso;
const ordenarCasos = (casos) => {
  const ordem = Object.keys(NOMES);
  const posicao = (c) => (ordem.indexOf(c) === -1 ? ordem.length : ordem.indexOf(c));
  return [...new Set(casos)].sort((a, b) => posicao(a) - posicao(b) || a.localeCompare(b));
};
const comAlfa = (hex, alfa) => {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${n >> 16}, ${(n >> 8) & 255}, ${n & 255}, ${alfa})`;
};

const quadro = context.panel.data.series[0];
const coluna = (nome) => {
  const campo = quadro && quadro.fields.find((f) => f.name === nome);
  return campo ? Array.from(campo.values) : [];
};
const semDados = (mensagem) => ({
  title: { text: mensagem, left: 'center', top: 'middle', textStyle: { color: tinta, fontSize: 13, fontWeight: 'normal' } },
});

const eixoValor = (extra) => Object.assign({
  type: 'value',
  scale: true,
  axisLine: { show: false },
  axisTick: { show: false },
  axisLabel: { color: tinta, fontSize: 11 },
  splitLine: { lineStyle: { color: grade, width: 1 } },
}, extra || {});
const eixoCategoria = (dados, extra) => Object.assign({
  type: 'category',
  data: dados,
  axisLine: { lineStyle: { color: grade } },
  axisTick: { show: false },
  axisLabel: { color: tinta, fontSize: 11 },
}, extra || {});
const tituloGrafico = (texto, extra) => Object.assign({
  text: texto,
  textStyle: { color: tintaForte, fontSize: 12, fontWeight: 600 },
}, extra || {});
const dica = (formatador) => ({
  backgroundColor: superficie,
  borderColor: grade,
  textStyle: { color: tintaForte, fontSize: 12 },
  formatter: formatador,
});

// Boxplot por caso, um gráfico por sensor. Caixa = quartis; linhas = percentis 5 e 95; losango = média.
if (!quadro || coluna('caso').length === 0) {
  return semDados('Sem leituras para os filtros escolhidos');
}
const sensores = [['mq3', 'MQ-3', 0], ['mq135', 'MQ-135', 0], ['umid', 'Umidade (%)', 1]];
const casos = coluna('caso');
const nomes = casos.map(nomeDoCaso);
const n = coluna('n');
const arredondar = (v, casas) => (v === null || v === undefined ? '–' : v.toFixed(casas));

const title = [];
const grid = [];
const xAxis = [];
const yAxis = [];
const series = [];
sensores.forEach(([chave, rotulo, casas], i) => {
  const esquerda = 5 + i * 32;
  title.push(tituloGrafico(rotulo, { left: `${esquerda}%`, top: 6 }));
  grid.push({ left: `${esquerda}%`, top: 40, width: '27%', bottom: 34, containLabel: true });
  xAxis.push(eixoCategoria(nomes, { gridIndex: i }));
  yAxis.push(eixoValor({ gridIndex: i }));
  const p = (nome) => coluna(`${chave}_${nome}`);
  const caixas = [p('p5'), p('p25'), p('p50'), p('p75'), p('p95')];
  series.push({
    name: rotulo,
    type: 'boxplot',
    xAxisIndex: i,
    yAxisIndex: i,
    boxWidth: [10, 40],
    data: casos.map((caso, k) => ({
      value: caixas.map((c) => c[k]),
      itemStyle: { color: comAlfa(corDoCaso(caso), 0.22), borderColor: corDoCaso(caso), borderWidth: 2 },
    })),
    tooltip: {
      ...dica((x) => {
        const k = x.dataIndex;
        return `<b>${rotulo} · ${nomes[k]}</b><br/>${n[k]} leituras<br/>`
          + `mediana ${arredondar(caixas[2][k], casas)}<br/>quartis ${arredondar(caixas[1][k], casas)} a ${arredondar(caixas[3][k], casas)}<br/>`
          + `percentis 5 a 95: ${arredondar(caixas[0][k], casas)} a ${arredondar(caixas[4][k], casas)}<br/>média ${arredondar(coluna(`${chave}_media`)[k], casas)}`;
      }),
    },
  });
  series.push({
    name: `${rotulo} (média)`,
    type: 'scatter',
    xAxisIndex: i,
    yAxisIndex: i,
    symbol: 'diamond',
    symbolSize: 11,
    z: 10,
    data: casos.map((caso, k) => ({
      value: [nomes[k], coluna(`${chave}_media`)[k]],
      itemStyle: { color: corDoCaso(caso), borderColor: superficie, borderWidth: 2 },
    })),
    label: { show: true, position: 'right', color: tinta, fontSize: 10, formatter: (x) => arredondar(x.value[1], casas) },
    tooltip: { show: false },
  });
});

return { title, grid, xAxis, yAxis, series, tooltip: { trigger: 'item' } };

